// Resolver o os_id real (interno Bom Saldo = 7+ dígitos)
const trigger = $('Trigger').first().json;
const supabase = $input.first().json;

// Prioridade: os_id_bomsaldo do Supabase > os_id do trigger
const osIdSupa = String(supabase.os_id_bomsaldo || '').replace(/[^0-9]/g, '');
const osIdTrigger = String(trigger.os_id || '').replace(/[^0-9]/g, '');

let osIdReal;
if (osIdSupa.length >= 7) {
  osIdReal = osIdSupa;
} else if (osIdTrigger.length >= 7) {
  osIdReal = osIdTrigger;
} else {
  return [{ json: { error: `VANDA: os_id '${trigger.os_id}' parece ser o código visível da OS, não o ID interno. O ID interno tem 7+ dígitos. Chame 'buscarContexto' para recuperar o os_id correto.` } }];
}

// Pegar hora_entrada/saida do Supabase se não vieram no trigger
const horaEntrada = trigger.hora_entrada || supabase.hora_entrada || null;
const horaSaida = trigger.hora_saida || supabase.hora_saida || null;

return [{ json: {
  ...trigger,
  os_id: osIdReal,
  os_codigo: trigger.os_codigo || supabase.os_codigo,
  hora_entrada: horaEntrada,
  hora_saida: horaSaida,
  produtos_json_supabase: supabase.produtos_json,
  servicos_json_supabase: supabase.servicos_json
} }];

const triggerParams = $('Resolver OS ID').first().json;
const osResp = $input.first().json;

if (triggerParams.error) {
  return [{ json: { error: triggerParams.error } }];
}
if (!osResp || osResp.status === 'error' || !osResp.data) {
  const dt = osResp ? (osResp.message || JSON.stringify(osResp)) : 'erro desconhecido';
  return [{ json: { error: 'FALHA GRAVE AO BUSCAR OS. Erro API: ' + dt } }];
}

const osAtual = osResp.data;
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';
const today = new Date().toISOString().slice(0, 10);
const nowIso = new Date().toISOString();
const toBool = (v) => v === true || String(v || '').trim().toLowerCase() === 'true' || String(v || '').trim() === '1';
const toNumber = (v, fallback = 0) => { const n = Number(v); return Number.isFinite(n) ? n : fallback; };
const parseArray = (value) => {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try { const parsed = JSON.parse(value); return Array.isArray(parsed) ? parsed : []; } catch {}
  }
  return [];
};
const normalizeHora = (raw) => {
  if (isBlank(raw)) return null;
  const s = String(raw).trim();
  let m = s.match(/(?:^|\b)(\d{1,2}):(\d{2})(?::\d{2})?(?:\b|$)/);
  if (m) {
    const h = Number(m[1]); const min = Number(m[2]);
    if (h >= 0 && h <= 23 && min >= 0 && min <= 59) return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }
  m = s.match(/(?:^|\b)(\d{1,2})h\s*(\d{2})?(?:\b|$)/i);
  if (m) {
    const h = Number(m[1]); const min = Number(m[2] || '0');
    if (h >= 0 && h <= 23 && min >= 0 && min <= 59) return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }
  try {
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false });
    }
  } catch {}
  return null;
};
const minutesFromHHMM = (hhmm) => {
  const m = String(hhmm || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  return Number(m[1]) * 60 + Number(m[2]);
};
const calcTempo = (entrada, saida) => {
  const a = minutesFromHHMM(entrada);
  const b = minutesFromHHMM(saida);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  const diff = b - a;
  return diff >= 0 ? diff : null;
};
const uniqueBy = (items, getKey) => {
  const map = new Map();
  for (const item of items) { const key = getKey(item); if (key) map.set(key, item); }
  return [...map.values()];
};

let produtos = parseArray(triggerParams.produtos_json);
if (produtos.length === 0) produtos = parseArray(triggerParams.produtos_json_supabase);
let servicos = parseArray(triggerParams.servicos_json);
if (servicos.length === 0) servicos = parseArray(triggerParams.servicos_json_supabase);

const emGarantia = toBool(triggerParams.em_garantia);
const horaEntrada = normalizeHora(triggerParams.hora_entrada);
const horaSaida = normalizeHora(triggerParams.hora_saida);
const explicitSituacao = !isBlank(triggerParams.situacao_id) ? String(triggerParams.situacao_id) : null;
const closeRequested = emGarantia || explicitSituacao === '6237499' || String(triggerParams.status_os || '').toLowerCase() === 'concluida' || String(triggerParams.fase_ia || '').toLowerCase() === 'fechado' || toBool(triggerParams.fechar);
const statusAtual = String(osAtual.situacao_id || '');
const targetSituacao = explicitSituacao || (closeRequested ? '6237499' : (horaEntrada && !['6237499', '6237500'].includes(statusAtual) ? '6237498' : (statusAtual || '6237497')));
const isClosing = targetSituacao === '6237499' || closeRequested;
const dataEntrada = osAtual.data_entrada || osAtual.data || today;
const dataSaida = isClosing ? today : (osAtual.data_saida || '');
const tempoMin = calcTempo(horaEntrada, horaSaida);

let obsInterna = triggerParams.relatorio_tecnico || triggerParams.laudo || osAtual.observacoes_interna || '';
const linhas = [];
if (horaEntrada && !obsInterna.includes('[CHEGADA:')) linhas.push(`[CHEGADA: ${horaEntrada}]`);
if (horaSaida && !obsInterna.includes('[SAIDA:') && !obsInterna.includes('[SAÍDA:')) linhas.push(`[SAIDA: ${horaSaida}]`);
if (isClosing && !obsInterna.includes('[TEMPO:')) {
  if (Number.isFinite(tempoMin)) linhas.push(`[TEMPO: ${tempoMin} min]`);
  else linhas.push('[TEMPO: não calculado - horário incompleto]');
}
if (!isBlank(triggerParams.tecnico_nome) && !obsInterna.includes('[TECNICO:')) {
  linhas.push(`[TECNICO: ${String(triggerParams.tecnico_nome).trim()}]`);
}
if (linhas.length) obsInterna = (obsInterna ? obsInterna + '\n' : '') + linhas.join('\n');

const payload = {
  codigo: osAtual.codigo,
  cliente_id: osAtual.cliente_id,
  data: dataEntrada,
  data_entrada: dataEntrada,
  observacoes: triggerParams.observacoes_orientacao || osAtual.observacoes || '',
  observacoes_interna: obsInterna.trim(),
  situacao_id: targetSituacao
};
if (dataSaida) { payload.data_saida = dataSaida; payload.saida = dataSaida; }
let tecnicoBomSaldoId = String(triggerParams.tecnico_bomsaldo_id || triggerParams.tecnico_id || '').replace(/\D/g, '');
if (tecnicoBomSaldoId.length > 8) tecnicoBomSaldoId = null;
if (tecnicoBomSaldoId) payload.tecnico_id = tecnicoBomSaldoId;
if (!isBlank(triggerParams.tecnico_nome)) payload.nome_tecnico = String(triggerParams.tecnico_nome).trim();

let equipamentosArray = osAtual.equipamentos || [];
if (triggerParams.equipamento) {
  equipamentosArray = [{ equipamento: {
    equipamento: triggerParams.equipamento || '',
    marca: triggerParams.marca || '',
    modelo: triggerParams.modelo || '',
    defeitos: triggerParams.defeito || '',
    solucao: triggerParams.solucao || '',
    laudo: triggerParams.relatorio_tecnico || triggerParams.laudo || ''
  }}];
}
if (equipamentosArray.length > 0) payload.equipamentos = equipamentosArray;

const produtosArray = [];
for (const p of osAtual.produtos || []) {
  const x = p.produto || p;
  if (!x.produto_id) continue;
  produtosArray.push({ produto: {
    produto_id: String(x.produto_id), variacao_id: String(x.variacao_id || ''),
    quantidade: String(x.quantidade || '1'), valor_venda: emGarantia ? '0' : String(x.valor_venda || '0'),
    tipo_desconto: x.tipo_desconto || 'R$', desconto_valor: String(x.desconto_valor || '0'), desconto_porcentagem: String(x.desconto_porcentagem || '0')
  }});
}
for (const p of produtos) {
  const x = p.produto || p;
  const pid = x.produto_id || x.id;
  if (!pid) continue;
  produtosArray.push({ produto: {
    produto_id: String(pid), variacao_id: String(x.variacao_id || ''),
    quantidade: String(x.quantidade || '1'), valor_venda: emGarantia ? '0' : String(x.valor_venda ?? '0'),
    tipo_desconto: x.tipo_desconto || 'R$', desconto_valor: String(x.desconto_valor || '0'), desconto_porcentagem: String(x.desconto_porcentagem || '0')
  }});
}
const produtosUnicos = uniqueBy(produtosArray, (p) => `${p.produto.produto_id}:${p.produto.variacao_id}`);
if (produtosUnicos.length) payload.produtos = produtosUnicos;

const servicosArray = [];
for (const s of osAtual.servicos || []) {
  const x = s.servico || s;
  if (!x.servico_id) continue;
  servicosArray.push({ servico: {
    servico_id: String(x.servico_id), quantidade: String(x.quantidade || '1'), valor_venda: emGarantia ? '0' : String(x.valor_venda || '0'),
    tipo_desconto: x.tipo_desconto || 'R$', desconto_valor: String(x.desconto_valor || '0'), desconto_porcentagem: String(x.desconto_porcentagem || '0')
  }});
}
for (const s of servicos) {
  const x = s.servico || s;
  const sid = x.servico_id || x.id;
  if (!sid) continue;
  servicosArray.push({ servico: {
    servico_id: String(sid), quantidade: String(x.quantidade || '1'), valor_venda: emGarantia ? '0' : String(x.valor_venda ?? '0'),
    tipo_desconto: x.tipo_desconto || 'R$', desconto_valor: String(x.desconto_valor || '0'), desconto_porcentagem: String(x.desconto_porcentagem || '0')
  }});
}
const servicosUnicos = uniqueBy(servicosArray, (s) => `${s.servico.servico_id}`);
if (servicosUnicos.length) payload.servicos = servicosUnicos;

const camposExtras = [];
if (triggerParams.observacoes_orientacao) camposExtras.push({ atributo_os: { atributo_id: '58530', valor: triggerParams.observacoes_orientacao } });
if (triggerParams.relatorio_tecnico || triggerParams.laudo) camposExtras.push({ atributo_os: { atributo_id: '58528', valor: triggerParams.relatorio_tecnico || triggerParams.laudo } });
const tipoServico = emGarantia ? 'Garantia' : (triggerParams.tipo_servico || '');
if (tipoServico) camposExtras.push({ atributo_os: { atributo_id: '58529', valor: tipoServico } });
if (camposExtras.length) payload.atributos_os = camposExtras;

let total = 0;
for (const p of produtosUnicos) total += toNumber(p.produto.quantidade) * toNumber(p.produto.valor_venda);
for (const s of servicosUnicos) total += toNumber(s.servico.quantidade) * toNumber(s.servico.valor_venda);
if (emGarantia) total = 0;
const formaPagamento = (() => {
  const tp = String(triggerParams.tipo_pagamento || '').toLowerCase();
  if (tp.includes('pix') && tp.includes('inter')) return '4377571';
  if (tp.includes('pix') && tp.includes('cora')) return '5108978';
  if (tp.includes('pix')) return '4354384';
  if (tp.includes('boleto') && tp.includes('cora')) return '4384233';
  if (tp.includes('boleto') && tp.includes('inter')) return '4365900';
  if (tp.includes('dinheiro') || tp.includes('especie') || tp.includes('espécie')) return '4354377';
  if (tp.includes('credito') || tp.includes('crédito')) return '4364858';
  if (tp.includes('debito') || tp.includes('débito')) return '4364859';
  if (tp.includes('boleto') || tp.includes('faturad') || tp.includes('escritorio')) return '4366641';
  return osAtual.pagamentos?.[0]?.pagamento?.forma_pagamento_id || triggerParams.forma_pagamento_id || '4366641';
})();
payload.pagamentos = [{ pagamento: { data_vencimento: today, valor: total.toFixed(2), forma_pagamento_id: formaPagamento } }];

const supabasePatch = { atualizado_em: nowIso };
if (horaEntrada) { supabasePatch.hora_entrada = horaEntrada; supabasePatch.checkin_registrado = true; }
if (horaSaida) { supabasePatch.hora_saida = horaSaida; supabasePatch.checkout_registrado = true; }
if (Number.isFinite(tempoMin)) supabasePatch.tempo_atendimento_min = tempoMin;
if (!isBlank(triggerParams.tecnico_id)) supabasePatch.tecnico_id = String(triggerParams.tecnico_id);
if (!isBlank(triggerParams.tecnico_nome)) supabasePatch.tecnico_nome = String(triggerParams.tecnico_nome);
if (!isBlank(triggerParams.tecnico_whatsapp)) supabasePatch.tecnico_whatsapp = String(triggerParams.tecnico_whatsapp);
for (const f of ['equipamento','marca','modelo','defeito','causa','solucao','relatorio_tecnico','tipo_servico','observacoes_orientacao','tipo_pagamento','forma_pagamento_id']) {
  if (!isBlank(triggerParams[f])) supabasePatch[f] = triggerParams[f];
}
supabasePatch.em_garantia = emGarantia;
supabasePatch.valor_total = total;
if (produtosUnicos.length) supabasePatch.produtos_json = produtosUnicos;
if (servicosUnicos.length) supabasePatch.servicos_json = servicosUnicos;
if (isClosing) {
  supabasePatch.status_os = 'concluida';
  supabasePatch.fase_ia = 'fechado';
  supabasePatch.fechado_em = nowIso;
} else if (targetSituacao === '6237498') {
  supabasePatch.status_os = 'em_andamento';
  supabasePatch.fase_ia = 'coleta_tecnica';
}

return [{ json: {
  os_id: triggerParams.os_id, os_codigo: triggerParams.os_codigo, payload, supabase_patch: supabasePatch,
  tempo_atendimento_min: Number.isFinite(tempoMin) ? tempoMin : null,
  hora_entrada_normalizada: horaEntrada, hora_saida_normalizada: horaSaida,
  contrato_bomsaldo: { horas_nativas_suportadas: false, datas_nativas_suportadas: true, tecnico_nativo_suportado: true }
} }];

const payloadJson = $('Montar Payload').first().json;
if (payloadJson.error) {
  return [{ json: { sucesso: false, resultado: payloadJson.error } }];
}
const data = $('PUT Atualizar OS').first().json;
if (data.status === 'error' || data.error || data.message || (data.statusCode && data.statusCode >= 400)) {
  const detalheErro = data.message || data.error || JSON.stringify(data);
  return [{ json: { sucesso: false, resultado: 'Erro fatal ao SALVAR a OS no Bom Saldo. Detalhes: ' + detalheErro, bom_saldo: data } }];
}
const supabase = $('Atualizar OS Supabase HTTP').first().json;
return [{ json: {
  sucesso: true,
  resultado: 'OS #' + (payloadJson.os_codigo || '') + ' atualizada no Bom Saldo e sincronizada no Supabase.',
  os_codigo: payloadJson.os_codigo,
  os_id_bomsaldo: payloadJson.os_id,
  hora_entrada: payloadJson.hora_entrada_normalizada,
  hora_saida: payloadJson.hora_saida_normalizada,
  tempo_atendimento_min: payloadJson.tempo_atendimento_min,
  contrato_bomsaldo: payloadJson.contrato_bomsaldo,
  bom_saldo: data.data || data,
  supabase
} }];
